def valida(record):
    if "quota" not in record:
        raise KeyError("manca la chiave quota")
    q = record["quota"]
    if not isinstance(q, (int, float)):
        raise TypeError(f"quota non numerica: {type(q).__name__}")
    if q < 0:
        raise ValueError(f"quota negativa: {q} m")
    return q
